-- ************************************** Employee
CREATE TABLE Employee
(
 employee_number     numeric(5) NOT NULL,
 emp_employee_number numeric(5),
 division_number     numeric(5),
 first_name          char(30),
 last_name           char(30),
 employee_function   char(30),
 employee_salary     numeric(8,2),

 CONSTRAINT PK_Employee PRIMARY KEY ( employee_number ),
 CONSTRAINT FK_Employee_Division FOREIGN KEY ( division_number ) REFERENCES Division ( division_number ),
 CONSTRAINT FK_Employee_Supervisor FOREIGN KEY ( emp_employee_number ) REFERENCES Employee ( employee_number )
);
